class User {
    String username;

    User(String email) {
        username = email;
    }

    User(int phoneNumber) {
        username = "PH-" + phoneNumber;
    }
}

public class Main {
    public static void main(String[] args) {
        User u1 = new User("dev@java.com");
        User u2 = new User(98765);
        System.out.println("User 1: " + u1.username + " | User 2: " + u2.username);
    }
}

class Circle {
    double radius;

    Circle() {
        radius = 1.0;
    }

    Circle(double r) {
        radius = r;
    }

    double getCircumference() {
        return 2 * 3.14 * radius;
    }
}

public class Main {
    public static void main(String[] args) {
        Circle c1 = new Circle();
        Circle c2 = new Circle(5.0);
        System.out.printf("C1: %.2f | C2: %.2f%n", c1.getCircumference(), c2.getCircumference());
    }
}
